using UnityEngine;
using UnityEngine.UI;
using TMPro;

// Generated by AI
// Manages the cultural information cards displayed after collecting items.
public class CulturalInfoManager : MonoBehaviour
{
    [Header("Information Card")]
    public GameObject infoPanel;
    public Image itemImage;
    public TMP_Text itemNameText;
    public TMP_Text regionText;
    public TMP_Text descriptionText;

    [Header("Continue Button")]
    public Button continueButton;

    private void Start()
    {
        infoPanel.SetActive(false);

        continueButton.onClick.AddListener(CloseInfoCard);
    }

    public void ShowInfo(ItemPickup item)
    {
        if (item == null)
            return;

        itemNameText.text = item.itemName;
        regionText.text = item.regionName;
        descriptionText.text = item.culturalFact;

        itemImage.sprite = item.itemImage;
        itemImage.enabled = item.itemImage != null;

        infoPanel.SetActive(true);

        Time.timeScale = 0f;
    }

    private void CloseInfoCard()
    {
        infoPanel.SetActive(false);

        GameController controller =
            Object.FindFirstObjectByType<GameController>();

        if (controller != null)
        {
            controller.ContinuarDespuesFicha();
        }
        else
        {
            Time.timeScale = 1f;
        }
    }
}

